<!doctype html>
<html lang="en"><?php include '../include/page-config.php'; require_once '../data/demo-data.php'; include '../include/head.php'; ?>
<style>.demo-label{font-size:.75rem;color:var(--bs-secondary-color)}.barcode-card{border:1px dashed #adb5bd;border-radius:.35rem;padding:.65rem;text-align:center;background:#fff;color:#111}.barcode-card svg{max-width:100%;height:54px}@media print{body *{visibility:hidden!important}#print-area,#print-area *{visibility:visible!important}#print-area{position:absolute;left:0;top:0;width:100%;display:grid!important;grid-template-columns:repeat(3,1fr);gap:5mm;padding:5mm}.no-print{display:none!important}}</style>
<body class="layout-fixed sidebar-expand-lg bg-body-tertiary"><div class="app-wrapper"><?php include '../layout/header.php'; include '../layout/sidebar.php'; ?><main class="app-main"><?php include '../layout/page-header.php'; ?><div class="app-content"><div class="container-fluid"><div class="row g-3"><div class="col-xl-4"><div class="card"><div class="card-header"><h3 class="card-title">Label settings</h3></div><div class="card-body"><label class="form-label">Product</label><select class="form-select mb-3" id="tag-product"><?php foreach($demoProducts as $p): ?><option value="<?= (int)$p['id'] ?>"><?= htmlspecialchars($p['product'].' · '.$p['sku']) ?></option><?php endforeach; ?></select><label class="form-label">Number of labels</label><input id="tag-quantity" class="form-control mb-3" type="number" min="1" max="500" value="1"><label class="form-label">Label size</label><select class="form-select mb-3" id="tag-size"><option>50 × 25 mm</option><option selected>60 × 30 mm</option><option>75 × 50 mm</option></select><div class="form-check mb-3"><input class="form-check-input" id="show-price" type="checkbox" checked><label class="form-check-label" for="show-price">Show selling price</label></div><button id="generate-labels" class="btn btn-primary w-100">Generate labels</button><p class="small text-body-secondary mt-3">Internal barcodes use Code 128. Manufacturer barcodes should be retained when adding real products.</p></div></div></div><div class="col-xl-8"><div class="card"><div class="card-header"><h3 class="card-title">Preview</h3><button id="print-labels" class="btn btn-sm btn-outline-primary ms-auto">Print labels</button></div><div class="card-body"><div id="print-area" class="row g-2"></div></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script>(()=>{const products=<?= json_encode($demoProducts,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;const area=document.getElementById('print-area');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const p=products.find(x=>String(x.id)===document.getElementById('tag-product').value);if(!p)return;const n=Math.max(1,Math.min(500,Number(document.getElementById('tag-quantity').value)||1));area.innerHTML=Array.from({length:n},()=>'<div class="col-4"><div class="barcode-card"><strong>'+esc(p.product)+'</strong><svg class="barcode"></svg><div class="small">'+esc(p.barcode)+'</div>'+(document.getElementById('show-price').checked?'<strong>Rs. '+Number(p.price).toFixed(0)+'</strong>':'')+'</div></div>').join('');area.querySelectorAll('svg').forEach(s=>JsBarcode(s,p.barcode,{format:'CODE128',displayValue:false,margin:2,height:38,width:1.5}));}document.getElementById('generate-labels').onclick=render;document.getElementById('print-labels').onclick=()=>window.print();render();})();</script></div></div></main><?php include '../layout/footer.php'; ?></div><?php include '../include/footer-scripts.php'; ?></body></html>